112			@Parameter(name = "X-Model", description = "단말 모델명", example = "SM-G998N", required = true, in = ParameterIn.HEADER),
113			@Parameter(name = "X-OS-Version", description = "Android OS 버전", example = "14", required = true, in = ParameterIn.HEADER),
114			@Parameter(name = "X-App-Version", description = "앱 버전", example = "02.00.01", required = true, in = ParameterIn.HEADER)
115		})
116		@RequestBody(
117			description = "가입자 초기 정보 확인 요청",
118			required = true,
119			content = @Content(mediaType = "application/json",
120			schema = @Schema(type = "object"),
121			examples = @ExampleObject(value = "{\"ctn\":\"01012345678\",\"fcmToken\":\"fcm_token_value\"}"))
122		)
123		@NoAuth
124		@RequestMapping(value = "/init", method = RequestMethod.POST)
125		public String init(@RequestJson(requiredValues = {"ctn", "fcmToken"}) ParamMap param,
126						   @RequestHeader(value = "X-Manufacturer", required = true) String manufacturer,
127						   @RequestHeader(value = "X-Model", required = true) String deviceModel,
128						   @RequestHeader(value = "X-OS-Version", required = true) String osVersion,
