		@Parameter(name = "X-Manufacturer", description = "단말 제조사", example = "samsung", in = ParameterIn.HEADER),
		@Parameter(name = "X-Model", description = "단말 모델명", example = "SM-G998N", in = ParameterIn.HEADER),
		@Parameter(name = "X-OS-Version", description = "Android OS 버전", example = "14", in = ParameterIn.HEADER),
		@Parameter(name = "X-App-Version", description = "앱 버전", example = "02.00.01", in = ParameterIn.HEADER),
		@Parameter(name = "Authorization", description = "만료된 인증 토큰", example = "Bearer {EXPIRED_ACCESS_TOKEN}", required = true, in = ParameterIn.HEADER)
	})
	@RequestBody(
		description = "토큰 갱신 요청",
		required = true,
		content = @Content(mediaType = "application/json",
			schema = @Schema(type = "object"),
			examples = @ExampleObject(value = "{\"refreshToken\":\"refresh_token_value\"}"))
	)
	@RequestMapping(value = "/refresh", method = RequestMethod.POST)
	public String refreshTokenV2(@RequestJson(requiredValues = {"refreshToken"}) ParamMap param,
								 @RequestHeader(value = "X-Manufacturer", required = true) String manufacturer,
								 @RequestHeader(value = "X-Model", required = true) String deviceModel,
								 @RequestHeader(value = "X-OS-Version", required = true) String osVersion,
								 @RequestHeader(value = "X-App-Version", required = true) String appVersion,
								 @RequestHeader(value = "Authorization", required = true) String authorization,
								 HttpServletRequest request, Model model) throws LogicException {
		LogInfo logInfo = setDeviceLog(param, "S07");
		try {
			// TODO: service 호출
			logInfo.setRESULT_CODE("000");
		} catch (Exception e) {
			logInfo.setRESULT_CODE("999");
			throw e;
		} finally {
			lgLogger.info(logInfo.toString());
		}
		return JSON_VIEW;
	}

	private LogInfo setDeviceLog(ParamMap param, String serviceClass) {
		String clientName = "";
		if (!CommonUtil.isNull(param.getSessionAttribute("clientName"))) {
			clientName = CommonUtil.nvl((String)param.getSessionAttribute("clientName"));
		}
		LogInfo logInfo = new LogInfo("SVC"
				, param.getRequest().getRemoteAddr()
				, CommonUtil.nvl((String)param.getSessionAttribute("deviceInfo"))
				, CommonUtil.nvl((String)param.getSessionAttribute("osInfo"))
				, CommonUtil.nvl((String)param.getSessionAttribute("networkInfo"))
				, ""
				, CommonUtil.nvl((String)param.getSessionAttribute("deviceModel"))
				, "1"
				, ""																	// MEMBER_ID
				, serviceClass
				, ""
				, ""
				, ""
				, CommonUtil.nvl((String)param.getSessionAttribute("exceptionPolicy"))
				, clientName);
		if (!CommonUtil.isNull(param.getSessionAttribute("memberSeq"))) {
			logInfo.setMEMBER_ID(CommonUtil.memberIdFormat(param.getSessionLong("memberSeq")));
		}
		if (!CommonUtil.isNull(param.getSessionAttribute("clientSeq"))) {
			logInfo.setCLIENT_ID(CommonUtil.clientIdFormat(param.getSessionLong("clientSeq")));
		}
		return logInfo;
	}
}

