		dao.removeSMSInfo(accountSeq);
	} else if ("02".equals(authzCode) || "03".equals(authzCode) || "05".equals(authzCode)) {
		ResultMap clientInfo = dao.getClientSeqFromAccountSeq(accountSeq);
		session.setAttribute("loginClientSeq", clientInfo.getLong("clientSeq"));
