		session.setAttribute("loginQuotaOnOff", clientInfo.getString("quotaOnOff"));
		param.setSessionValue("loginUnauthorizedTrafficOnOff", clientInfo.getString("unauthorizedTrafficOnOff"));
		param.setSessionValue("loginMemberUsageStatsOnOff", clientInfo.getString("memberUsageStatsOnOff"));
		param.setSessionValue("loginWorkingHoursOnOff", clientInfo.getString("workingHoursOnOff"));
		param.setSessionValue("loginCpMemberUsageStatsOnOff", clientInfo.getString("cpMemberUsageStatsOnOff"));
		param.setSessionValue("lbspZoneInOutOnOff", clientInfo.getString("lbspZoneInOutOnOff"));

		String sqlSessionTemplate = dao.getClientSqlSessionTemplate(clientInfo.getLong("clientSeq"));
		if (!CommonUtil.isNull(sqlSessionTemplate)) {
			param.setSessionValue(Constants.SQL_SESSION_TEMPLATE_NAME, sqlSessionTemplate + "SqlSessionTemplate");
			param.setSessionValue(Constants.SQL_TRANSACTION_MANAGER_NAME, sqlSessionTemplate + "TransactionManager");
		}

		if (Authz.NORMAL.equals(authzCode)) {
			logger.info("[STEP {}] - Client admin login success", ++ logSeq);

