    "controllerFile": "src/main/java/com/ahope/ds/web/superadmin/client/controller/ClientController.java",
    "handler": "modifyClientCancel"
  },
  "className": "ClientCancelBlackBoxTest",
  "sqlSlug": "super-client-cancel",
  "docLines": [
    "인증: SuperAdminLoginInterceptor — AUTHZ 01(슈퍼) 또는 07(시스템)만 /web/super/admin/clients/** 접근 가능 (loginAdmin으로 2차 SMS 인증까지 수행).",
    "요청: clientSeq path 변수만 사용, 필수 파라미터 없음.",
    "응답: ResultMap { err } — LPS 가입자 존재 시 err=001, 정상 시 CANCEL_STATUS '01'→'02' 전환 후 err=000 (getClient가 null이어도 예외 없이 err=000으로 통과).",
    "클래스 내 모든 테스트는 동일한 슈퍼관리자 계정(seed ACC/ID)으로 로그인한다."
  ],
  "seedParams": [
    {"name": "ACC", "kind": "seq"},
    {"name": "CLIENT", "kind": "seq", "offset": 1},
    {"name": "ID", "kind": "id", "prefix": "bbcanc"}
  ],
  "auth": {
    "type": "admin",
    "idParam": "ID",
    "password": "Test1234!",
    "accountSeqParam": "ACC"
  },
  "setupSql": "DELETE FROM ACCOUNT_SMS WHERE ACCOUNT_SEQ = ${ACC};\nINSERT INTO ACCOUNT (ACCOUNT_SEQ, ID, PW, PW_UPT_DATE, NAME, PHONE, PHONE_HASH, AUTHZ, STATUS, REG_TIME, REG_ACCOUNT_SEQ, CONSENT_FORM_EXCEPTION_YN)\nVALUES (${ACC}, '${ID}', '{pbkdf2}00112233445566778899aabbccddeeff00112233445566778899aabbccddeeff93d298d38be09983b622fd932768073b722d13f0afd43431a9f81e2350841697', NOW(), 'BBTester', 'enc', CONCAT('h', ${ACC}), '01', '01', NOW(), 1, 'n');\n\nINSERT INTO CLIENT (CLIENT_SEQ, CLIENT_NAME, MANAGER_NAME, CANCEL_STATUS, REG_TIME, CLIENT_REG_ACCOUNT_SEQ)\nVALUES (${CLIENT}, 'BBTargetClient', 'BBmgr', '01', NOW(), 1);\nINSERT INTO CLIENT_MULTI_LANG_TEXT (CLIENT_MULTI_LANG_SEQ, CLIENT_SEQ, LANG, SUB_TITLE)\nVALUES (${CLIENT}, ${CLIENT}, 'ko', 'BBFactory');\nINSERT INTO CLIENT_ADDITIONAL_INFO (ADDITIONAL_INFO_SEQ, CLIENT_SEQ)\nVALUES (${CLIENT}, ${CLIENT});\nINSERT IGNORE INTO POLICY (POLICY_SEQ, POLICY_NAME) VALUES (1, 'DefaultPolicy');\nINSERT IGNORE INTO CLIENT_POLICY (CLIENT_SEQ, POLICY_SEQ) VALUES (${CLIENT}, 1);",
  "teardownSql": "DELETE FROM CLIENT_POLICY WHERE CLIENT_SEQ = ${CLIENT};\nDELETE FROM CLIENT_ADDITIONAL_INFO WHERE CLIENT_SEQ = ${CLIENT};\nDELETE FROM CLIENT_MULTI_LANG_TEXT WHERE CLIENT_SEQ = ${CLIENT};\nDELETE FROM CLIENT WHERE CLIENT_SEQ = ${CLIENT};\nDELETE FROM ACCOUNT_SMS WHERE ACCOUNT_SEQ = ${ACC};\nDELETE FROM ACCOUNT WHERE ACCOUNT_SEQ = ${ACC};",
  "stubs": [],
  "tests": [
    {
      "name": "NTC_modifyClientCancel_joinToCancelRequest",
      "comment": "CANCEL_STATUS 01(가입) → 02(해지요청) 정상 전환",
      "pathParams": {"clientSeq": "${CLIENT}"},
      "expectStatus": 200,
      "expectBody": [
        {"path": "err", "equalTo": "000"}
      ]
    },
    {
      "name": "VTC_modifyClientCancel_nonexistentClientSeq_noop",
      "comment": "존재하지 않는 clientSeq — 리소스 존재 검증이 없어 예외 없이 err=000",
      "pathParams": {"clientSeq": "919191919"},
      "expectStatus": 200,
      "expectBody": [
        {"path": "err", "equalTo": "000"}
      ]
    },
    {
      "name": "VTC_modifyClientCancel_nonNumericClientSeq_returnsErr999",
      "comment": "clientSeq가 long으로 파싱 불가 → 일반 예외 처리(999)",
      "headers": {"X-Requested-With": "XMLHttpRequest"},
      "pathParams": {"clientSeq": "abc"},
      "expectStatus": 200,
      "expectBody": [
        {"path": "err", "equalTo": "999"}
      ]
    }
  ]
}

