    "type": "admin",
    "idParam": "ID",
    "password": "Test1234!",
    "accountSeqParam": "ACC"
  },
  "setupSql": "DELETE FROM ACCOUNT_SMS WHERE ACCOUNT_SEQ = ${ACC};\nINSERT INTO ACCOUNT (ACCOUNT_SEQ, ID, PW, PW_UPT_DATE, NAME, PHONE, PHONE_HASH, AUTHZ, STATUS, REG_TIME, REG_ACCOUNT_SEQ, CONSENT_FORM_EXCEPTION_YN)\nVALUES (${ACC}, '${ID}', '{pbkdf2}00112233445566778899aabbccddeeff00112233445566778899aabbccddeeff93d298d38be09983b622fd932768073b722d13f0afd43431a9f81e2350841697', NOW(), 'BBTester', 'enc', CONCAT('h', ${ACC}), '07', '01', NOW(), 1, 'n');",
  "teardownSql": "DELETE FROM ACCOUNT_SMS WHERE ACCOUNT_SEQ = ${ACC};\nDELETE FROM ACCOUNT WHERE ACCOUNT_SEQ = ${ACC};",
  "stubs": [],
  "tests": [
    {
      "name": "NTC_makeCanceledMemberExcel_systemAdmin_success",
      "comment": "시스템 관리자가 정상 파라미터로 요청하면 비동기 생성이 즉시 접수된다",
      "headers": {"X-Requested-With": "XMLHttpRequest"},
      "form": {"searchType": "NAME", "searchValue": "", "searchStartDate": "20260101", "searchEndDate": "20261231", "excelReason": "업무용"},
      "expectStatus": 200,
      "expectBody": [
        {"path": "err", "equalTo": "000"}
