      "headers": {"X-Requested-With": "XMLHttpRequest"},
      "form": {"searchType": "CTN", "searchValue": "01099998888", "searchStartDate": "20260101", "searchEndDate": "20261231", "excelReason": "업무용"},
      "expectStatus": 200,
      "expectBody": [
        {"path": "err", "equalTo": "000"}
      ]
    }
  ]
}

