import org.junit.jupiter.api.TestInfo;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

import io.restassured.filter.cookie.CookieFilter;

/**
 * Black-Box API Integration Test (template-rendered)
 *
 * @target-controller QuotaController (src/main/java/com/ahope/ds/web/admin/quota/controller/QuotaController.java)
 * @target-api DELETE /web/admin/quota/groups
 *
 * 실제 매핑 경로는 클래스 '/web/admin/quota' + 메서드 'groups' 조합으로 /web/admin/quota/groups 이다 (작업 지시서의 /web/admin/quotagroups는 오기).
 * 인증: AdminLoginInterceptor — /web/admin/quota.* 는 session.loginQuotaOnOff=='01' 이어야 통과 (CLIENT_ADDITIONAL_INFO.QUOTA_ONOFF 로 로그인 시 세팅됨).
 * 요청: memberGroupSeqs[] (long[], 필수, required 기본값 true) — 없으면 MissingServletRequestParameterException.
 * 응답: ResultMap { err } — 정상 000/removeCnt, 대상 없음 008(GROUP_NOT_FOUND).
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class QuotaGroupDeleteBlackBoxTest {

    private Map<String, String> seed(TestInfo info) {
        long seq = testSeq(info);
        return Map.of(
                "ACC", Long.toString(seq),
                "CLIENT", Long.toString(seq + 1),
                "GROUP", Long.toString(seq + 2),
                "ID", "bbquota" + testId(info));
    }

    private CookieFilter arrange(Map<String, String> p) {
        executeSqlTemplate("sql/quota-groups-delete-teardown.sql", p);
        executeSqlTemplate("sql/quota-groups-delete-setup.sql", p);
        return loginAdmin(p.get("ID"), "Test1234!", Long.parseLong(p.get("ACC")));
    }

    @Test
    void NTC_deleteGroup_success(TestInfo info) {
        // 고객사 소속 그룹 1건 삭제 성공
        Map<String, String> p = seed(info);
        CookieFilter cookies = arrange(p);
        try {
            given().filter(cookies).baseUri(BASE_URL)
                    .queryParam("memberGroupSeqs[]", p.get("GROUP"))
            .when()
                    .delete("/web/admin/quota/groups")
            .then()
                    .statusCode(200)
                    .body("err", equalTo("000"))
                    .body("removeCnt", equalTo(1));
        } finally {
            executeSqlTemplate("sql/quota-groups-delete-teardown.sql", p);
        }
    }

    @Test
    void VTC_deleteGroup_groupNotFound_returnsErr008(TestInfo info) {
        // 존재하지 않는 그룹 시퀀스 → GROUP_NOT_FOUND(008)
        Map<String, String> p = seed(info);
        CookieFilter cookies = arrange(p);
        try {
            given().filter(cookies).baseUri(BASE_URL)
                    .queryParam("memberGroupSeqs[]", "918273645")
            .when()
                    .delete("/web/admin/quota/groups")
            .then()
                    .statusCode(200)
                    .body("err", equalTo("008"));
        } finally {
            executeSqlTemplate("sql/quota-groups-delete-teardown.sql", p);
        }
    }

    @Test
    void VTC_deleteGroup_missingParam_returnsErr999(TestInfo info) {
        // memberGroupSeqs[] 파라미터 누락 → MissingServletRequestParameterException → 일반 예외 처리(999)
        Map<String, String> p = seed(info);
        CookieFilter cookies = arrange(p);
        try {
            given().filter(cookies).baseUri(BASE_URL)
                    .header("X-Requested-With", "XMLHttpRequest")
            .when()
                    .delete("/web/admin/quota/groups")
            .then()
                    .statusCode(200)
                    .body("err", equalTo("999"));
        } finally {
            executeSqlTemplate("sql/quota-groups-delete-teardown.sql", p);
        }
    }
}

