import org.junit.jupiter.api.parallel.ExecutionMode;

import io.restassured.filter.cookie.CookieFilter;
import io.restassured.http.ContentType;

/**
 * Black-Box API Integration Test (template-rendered)
 *
 * @target-controller CryptoController (src/main/java/com/ahope/ds/web/superadmin/crypto/controller/CryptoController.java)
 * @target-api POST /web/super/admin/crypto/personal
 *
 * 인증: SuperAdminLoginInterceptor — /web/super/admin/crypto/** 는 SUPER(01) 화이트리스트에 없어 AUTHZ=07(시스템) 계정만 통과.
 * 요청: cryptoContent (필수, RequestParamMap requiredValues) — 실제 AWS KMS로 암호화된 값이 아니면 복호화 실패.
 * 응답: ResultMap { err, cryptoResult } — 복호화 실패 시 err=115(RuntimeException) 또는 001(필수값 누락, RuntimeLogicException).
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class CryptoPersonalDecryptionBlackBoxTest {

    private Map<String, String> seed(TestInfo info) {
        long seq = testSeq(info);
        return Map.of(
                "ACC", Long.toString(seq),
                "ID", "bbcrypto" + testId(info));
    }

    private CookieFilter arrange(Map<String, String> p) {
        executeSqlTemplate("sql/crypto-personal-teardown.sql", p);
        executeSqlTemplate("sql/crypto-personal-setup.sql", p);
        return loginAdmin(p.get("ID"), "Test1234!", Long.parseLong(p.get("ACC")));
    }

    @Test
    void NTC_getPersonalDecryption_invalidCiphertext_returnsErr115(TestInfo info) {
        // KMS로 암호화되지 않은 평문을 넘기면 복호화가 RuntimeException으로 실패 → err=115
        Map<String, String> p = seed(info);
        CookieFilter cookies = arrange(p);
        try {
            given().filter(cookies).baseUri(BASE_URL)
                    .contentType(ContentType.URLENC)
                    .formParam("cryptoContent", "not-a-valid-ciphertext!!")
            .when()
                    .post("/web/super/admin/crypto/personal")
            .then()
                    .statusCode(200)
                    .body("err", equalTo("115"));
        } finally {
            executeSqlTemplate("sql/crypto-personal-teardown.sql", p);
        }
    }

    @Test
    void VTC_getPersonalDecryption_missingCryptoContent_returnsErr001(TestInfo info) {
        // cryptoContent 누락 → RequestParamMap requiredValues 검증 실패
        Map<String, String> p = seed(info);
        CookieFilter cookies = arrange(p);
        try {
            given().filter(cookies).baseUri(BASE_URL)
                    .header("X-Requested-With", "XMLHttpRequest")
            .when()
                    .post("/web/super/admin/crypto/personal")
            .then()
                    .statusCode(200)
                    .body("err", equalTo("001"));
        } finally {
            executeSqlTemplate("sql/crypto-personal-teardown.sql", p);
        }
    }

    @Test
    void VTC_getPersonalDecryption_whitespaceCryptoContent_returnsErr115(TestInfo info) {
        // 공백만 있는 값은 필수값 검증은 통과하지만 trim 후 복호화 실패
        Map<String, String> p = seed(info);
        CookieFilter cookies = arrange(p);
        try {
            given().filter(cookies).baseUri(BASE_URL)
                    .contentType(ContentType.URLENC)
                    .formParam("cryptoContent", "   ")
            .when()
                    .post("/web/super/admin/crypto/personal")
            .then()
                    .statusCode(200)
                    .body("err", equalTo("115"));
        } finally {
            executeSqlTemplate("sql/crypto-personal-teardown.sql", p);
        }
    }
}
